@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @ref="_textareaRef" @bind="_content" @bind:event="oninput" rows="15" cols="80"></textarea>

<div style="margin-top: 0.5rem;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
    @if (_lastSavedAt is not null)
    {
        <span style="margin-left: 1rem;">Last saved at @_lastSavedAt</span>
    }
</div>

@code {
    private ElementReference _textareaRef;
    private NotepadInterop? _interop;
    private string _content = string.Empty;
    private string? _lastSavedAt;
    private string _savedContent = string.Empty;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            await _interop.InitializeAsync();

            var restored = await _interop.LoadAsync();
            if (restored is not null)
            {
                _content = restored;
                _savedContent = restored;
                StateHasChanged();
            }
        }
    }

    private async Task SaveNowAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(_content);
        _savedContent = _content;
        _lastSavedAt = DateTime.Now.ToString("HH:mm:ss");
        await _interop.SetUnsavedChanges(false);
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        _content = string.Empty;
        _savedContent = string.Empty;
        _lastSavedAt = null;
        await _interop.ClearAsync();
        await _interop.SetUnsavedChanges(false);
    }

    [JSInvokable]
    public async Task OnAutoSave()
    {
        await InvokeAsync(async () =>
        {
            if (_interop is null) return;

            await _interop.SaveAsync(_content);
            _savedContent = _content;
            _lastSavedAt = DateTime.Now.ToString("HH:mm:ss");
            await _interop.SetUnsavedChanges(false);
            StateHasChanged();
        });
    }

    [JSInvokable]
    public Task NotifyContentChanged()
    {
        return InvokeAsync(() =>
        {
            var hasUnsaved = _content != _savedContent;
            _ = _interop?.SetUnsavedChanges(hasUnsaved);
        });
    }

    async ValueTask IAsyncDisposable.DisposeAsync()
    {
        if (_interop is not null)
            await _interop.DisposeAsync();
    }
}

const STORAGE_KEY = 'notepad-content';
const AUTOSAVE_INTERVAL_MS = 30000;
const ON_AUTO_SAVE = 'OnAutoSave';

let dotNetRef;
let autoSaveTimer;
let hasUnsavedChanges = false;

function handleBeforeUnload(e) {
    if (hasUnsavedChanges) {
        e.preventDefault();
        e.returnValue = '';
    }
}

export function initialize(dotNetReference) {
    dotNetRef = dotNetReference;

    window.addEventListener('beforeunload', handleBeforeUnload);

    autoSaveTimer = setInterval(async () => {
        try {
            await dotNetRef.invokeMethodAsync(ON_AUTO_SAVE);
        } catch { /* circuit disconnected */ }
    }, AUTOSAVE_INTERVAL_MS);
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
