const STORAGE_KEY = 'notepad-content';
const AUTOSAVE_INTERVAL_MS = 30000;
const ON_AUTO_SAVE = 'OnAutoSave';

let dotNetRef;
let autoSaveTimer;
let hasUnsavedChanges = false;

function handleBeforeUnload(e) {
    if (hasUnsavedChanges) {
        e.preventDefault();
        e.returnValue = '';
    }
}

export function initialize(dotNetReference) {
    dotNetRef = dotNetReference;

    window.addEventListener('beforeunload', handleBeforeUnload);

    autoSaveTimer = setInterval(async () => {
        try {
            await dotNetRef.invokeMethodAsync(ON_AUTO_SAVE);
        } catch { /* circuit disconnected */ }
    }, AUTOSAVE_INTERVAL_MS);
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function setUnsavedChanges(value) {
    hasUnsavedChanges = value;
}

export function dispose() {
    window.removeEventListener('beforeunload', handleBeforeUnload);
    if (autoSaveTimer) {
        clearInterval(autoSaveTimer);
        autoSaveTimer = null;
    }
    dotNetRef = null;
}

